-- Decoder template. The generated public payload also contains the WindUI MIT notice.
local function decode(packet)
    assert(type(packet.size)=="number" and packet.size>=0 and packet.size<=4*1024*1024,"Raven Hub: invalid payload size")
    assert(buffer and bit32,"Raven Hub requires Luau buffer and bit32")
    local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup={}
    for i=1,#alphabet do lookup[string.byte(alphabet,i)]=i-1 end
    local text=packet.data
    assert(#text%4==0 and #text<=6*1024*1024,"Raven Hub: invalid encoded payload")
    local padding=text:sub(-2)=="==" and 2 or text:sub(-1)=="=" and 1 or 0
    local raw=buffer.create(#text/4*3-padding)
    local write=0
    for i=1,#text,4 do
        local a,b,c,d=string.byte(text,i,i+3)
        local v1,v2,v3,v4=lookup[a],lookup[b],c==61 and 0 or lookup[c],d==61 and 0 or lookup[d]
        assert(v1 and v2 and v3 and v4,"Raven Hub: invalid base64")
        local word=v1*262144+v2*4096+v3*64+v4
        if write<buffer.len(raw) then buffer.writeu8(raw,write,math.floor(word/65536)%256) write+=1 end
        if write<buffer.len(raw) then buffer.writeu8(raw,write,math.floor(word/256)%256) write+=1 end
        if write<buffer.len(raw) then buffer.writeu8(raw,write,word%256) write+=1 end
        if i%65536==1 and i>1 then task.wait() end
    end
    assert(#packet.key==32,"Raven Hub: invalid packet key")
    for i=0,buffer.len(raw)-1 do
        buffer.writeu8(raw,i,bit32.bxor(buffer.readu8(raw,i),packet.key[i%#packet.key+1]))
        if i%65536==0 and i>0 then task.wait() end
    end
    local output=buffer.create(packet.size)
    local cursor,written,lastYield=0,0,0
    local function length(value)
        if value==15 then
            local extra
            repeat
                assert(cursor<buffer.len(raw),"Raven Hub: truncated block length")
                extra=buffer.readu8(raw,cursor) cursor+=1 value+=extra
            until extra~=255
        end
        return value
    end
    while cursor<buffer.len(raw) do
        local token=buffer.readu8(raw,cursor) cursor+=1
        local literals=length(bit32.rshift(token,4))
        assert(cursor+literals<=buffer.len(raw) and written+literals<=packet.size,"Raven Hub: invalid literal bounds")
        buffer.copy(output,written,raw,cursor,literals)
        cursor+=literals written+=literals
        if cursor==buffer.len(raw) then break end
        assert(cursor+2<=buffer.len(raw),"Raven Hub: truncated block offset")
        local offset=buffer.readu16(raw,cursor) cursor+=2
        assert(offset>0 and offset<=written,"Raven Hub: invalid block offset")
        local count=length(bit32.band(token,15))+4
        assert(written+count<=packet.size,"Raven Hub: invalid match bounds")
        for i=0,count-1 do buffer.writeu8(output,written+i,buffer.readu8(output,written-offset+i)) end
        written+=count
        if written-lastYield>=65536 then task.wait() lastYield=written end
    end
    assert(written==packet.size,"Raven Hub: decoded length mismatch")
    local a,b=1,0
    for i=0,written-1 do
        a=(a+buffer.readu8(output,i))%65521 b=(b+a)%65521
        if i%65536==0 and i>0 then task.wait() end
    end
    assert(b*65536+a==packet.checksum,"Raven Hub: corrupted payload")
    return buffer.tostring(output)
end

